    <script>
        (function() {
            const hour = new Date().getHours();
            let greeting = 'Morning';
            if (hour >= 12 && hour < 17) {
                greeting = 'Afternoon';
            } else if (hour >= 17) {
                greeting = 'Evening';
            }
            const el = document.getElementById('greetingTime');
            if (el) el.textContent = greeting;
        })();
    </script>
